<?php
namespace Tests\Unit;use PHPUnit\Framework\TestCase;
class ApprovedRankActivationPhaseSTest extends TestCase
{private function s(string$p):string{return file_get_contents(ROOTPATH.$p);}public function testWorkerSelectsOnlyDuePendingRanks():void{$s=$this->s('app/Services/ApprovedRankActivationService.php');self::assertStringContainsString("where('status','approved_pending_effectivity')",$s);self::assertStringContainsString("where('effectivity_date <=',date('Y-m-d'))",$s);}public function testLockingAndIdempotentStateValidation():void{$s=$this->s('app/Services/ApprovedRankActivationService.php');self::assertStringContainsString('FOR UPDATE',$s);self::assertStringContainsString('APPROVED_RANK_NOT_PENDING',$s);self::assertStringContainsString('RETRY_REQUIRES_ACTIVATION_FAILED',$s);}public function testPresentRankChangesOnlyInsideSuccessfulTransaction():void{$s=$this->s('app/Services/ApprovedRankActivationService.php');$method=$this->part($s,'private function activateLocked','private function persistFailure');self::assertStringContainsString("current_rank_title",$method);$failure=$this->part($s,'private function persistFailure','private function notifySuccess');self::assertStringNotContainsString('current_rank_title',$failure);}public function testHistoryIsClosedWithoutOverlapOrDeletion():void{$s=$this->s('app/Services/ApprovedRankActivationService.php');self::assertStringContainsString("'status'=>'historical'",$s);self::assertStringContainsString("strtotime(\$r['effectivity_date'].' -1 day')",$s);self::assertStringNotContainsString('delete()',$s);}public function testFailureAndRetryAttemptsAreImmutable():void{$m=$this->s('app/Database/Migrations/2026-09-15-000014_AddApprovedRankActivationRecovery.php');foreach(['personnel_rank_activation_attempts','activation_failed','retry_succeeded','failure_code']as$x)self::assertStringContainsString($x,$m);$s=$this->s('app/Services/ApprovedRankActivationService.php');self::assertStringContainsString('persistFailure',$s);self::assertStringContainsString('nextAttempt',$s);}public function testFailureDoesNotPretendPersistenceSucceeded():void{$s=$this->s('app/Services/ApprovedRankActivationService.php');self::assertStringContainsString('failure_state_persisted',$s);self::assertStringContainsString('RANK_ACTIVATION_FAILURE_STATE_NOT_PERSISTED',$s);}public function testHrRetryAndRecoveryHooksAreRestricted():void{$s=$this->s('app/Services/ApprovedRankActivationService.php');self::assertStringContainsString('$this->assertHr($actor)',$s);foreach(['correction_pending','cancellation_pending','RECOVERY_REQUIRES_ACTIVATION_FAILED']as$x)self::assertStringContainsString($x,$s);}public function testSuccessAndFailureNotificationsAreScoped():void{$s=$this->s('app/Services/ApprovedRankActivationService.php');foreach(['approved_rank_effective','approved_rank_effective_scope','approved_rank_activation_succeeded','approved_rank_activation_failed','DEPARTMENT_HEAD']as$x)self::assertStringContainsString($x,$s);self::assertStringNotContainsString('signed_document',$s);}public function testDeploymentCommandExists():void{$s=$this->s('app/Commands/ActivateDueApprovedRanks.php');self::assertStringContainsString('ranking:activate-due-approved-ranks',$s);self::assertStringContainsString('activateDue',$s);}private function part(string$s,string$a,string$b):string{$i=strpos($s,$a);$j=strpos($s,$b,$i);return substr($s,$i,$j-$i);}}
